// Canonical extraction merged from the three previously-duplicated Gatekeeper Code nodes.
const raw = (($json.raw_text || "").toString()).toLowerCase().trim();

// Level can arrive either as an abbreviation the parent typed (jss1, ss 2, ...)
// or already normalized to the full DB form by an upstream node (the text-command
// path passes 'junior secondary 1' straight through) -- match either.
const abbrevLevelRegex = /(jss|js|sss|ss)\s*([1-3])/i;
const fullLevelRegex = /(junior|senior)\s+secondary\s+([1-3])/i;

let normalizedLevel = "unknown";
let levelMatchStr = "";

const fullMatch = raw.match(fullLevelRegex);
const abbrevMatch = raw.match(abbrevLevelRegex);

if (fullMatch) {
    normalizedLevel = `${fullMatch[1].toLowerCase()} secondary ${fullMatch[2]}`;
    levelMatchStr = fullMatch[0];
} else if (abbrevMatch) {
    const type = abbrevMatch[1].toLowerCase();
    const num = abbrevMatch[2];
    if (type.includes('j')) {
        normalizedLevel = `junior secondary ${num}`;
    } else if (type.includes('s')) {
        normalizedLevel = `senior secondary ${num}`;
    }
    levelMatchStr = abbrevMatch[0];
}

// Union of noise words from all three original implementations (caption, form, command).
const noiseWords = /(payment|attached|receipt|of|fees|school|student|name|is|at|the|dear|bursar|ward|details)/gi;

let cleanedName = raw;
if (levelMatchStr) {
    cleanedName = cleanedName.replace(levelMatchStr, "");
}
cleanedName = cleanedName
    .replace(noiseWords, "")
    .replace(/[^\w\s]/g, "")
    .trim();

const nameParts = cleanedName.split(/\s+/).filter(part => part.length > 2);
const part1 = nameParts[0] || "unknown";
const part2 = nameParts[1] || part1;

return {
    student_name_raw: cleanedName,
    name_part_1: part1,
    name_part_2: part2,
    level: normalizedLevel,
    sender_phone: $json.sender_phone,
    context: $json.context,
    raw_text: raw
};

// Classify the (now un-LIMITed) result set.
// Gatekeeper Query has alwaysOutputData=true so a genuine zero-row match still
// produces one item -- but when there are truly zero rows, MySQL's node emits a
// placeholder item like {"success": true} with no student_id. Filtering on
// student_id below is what keeps that placeholder from being counted as a match.
//
// Retry semantics: a "not_found" result from THIS node is not necessarily final.
// The school's ERP promotes students to their next academic level before the new
// session starts, so a parent may still refer to the student's pre-promotion level.
// "Step Up Level" (downstream) decides whether a zero-row result is eligible for a
// single retry one level up, and "Classify Match (Retry)" re-runs this same
// classification against that retry query. retried_level is null here on the
// first pass -- it is only ever set by "Classify Match (Retry)" once a retry has
// actually been attempted, and it survives regardless of whether the retry itself
// found a match, so downstream messaging can say both levels were checked.
const rows = $input.all().map(item => item.json).filter(r => r && r.student_id);
const context = $('Extract Student Info').item.json.context;

if (rows.length === 0) {
    return {
        status: "not_found",
        student_id: null,
        full_name: null,
        level_name: null,
        candidates: [],
        context,
        retried_level: null
    };
}

if (rows.length === 1) {
    return {
        status: "found",
        student_id: rows[0].student_id,
        full_name: rows[0].full_name,
        level_name: rows[0].level_name,
        candidates: [],
        context,
        retried_level: null
    };
}

return {
    status: "ambiguous",
    student_id: null,
    full_name: null,
    level_name: null,
    candidates: rows.map(r => ({
        student_id: r.student_id,
        full_name: r.full_name,
        level_name: r.level_name
    })),
    context,
    retried_level: null
};

const gk = $json; // { status, student_id, full_name, level_name, candidates, context, retried_level }
const bursarPhone = "+234 916 258 3300";

let finalMessage = "";

if (gk.status === "not_found") {
  const retryHint = gk.context === "receipt"
    ? 'Please resend the receipt with a clearer caption containing the full name and class (e.g. "John Alabi, JSS2").'
    : 'Please resend your request with the correct full name and class (e.g. "BALANCE: John Alabi, JSS2").';

  // retried_level is set when a promotion-window retry (one level up) was
  // attempted and still came back empty -- say so honestly instead of
  // implying only the originally stated class was checked.
  const retriedNote = gk.retried_level
    ? `\n\nWe also checked *${gk.retried_level}* in case the student was recently promoted, but found no match there either.`
    : "";

  finalMessage = `❌ *Access Denied*

We couldn't find an active student matching that name/class linked to this phone number.${retriedNote}

This usually means:
- this phone number isn't on file as a parent/guardian/sponsor for that student, or
- the name or class given doesn't match anyone active in our records.

${retryHint}

📞 Still stuck? Chat the Bursar's Office directly at ${bursarPhone}.`;
} else if (gk.status === "ambiguous") {
  const candidatesList = (gk.candidates || [])
    .map(c => `- ${c.full_name} (${c.level_name})`)
    .join('\n');

  const retryHint = gk.context === "receipt"
    ? "Please resend the receipt with the student's full name spelled out completely so we can tell them apart."
    : "Please reply with the student's full name (or another identifying detail) so we can tell them apart.";

  finalMessage = `📘 *Bursar's Office: Multiple Matches*

We found more than one student matching that name and class linked to this phone number:
${candidatesList}

${retryHint}

📞 Need help? Chat the Bursar's Office directly at ${bursarPhone}.`;
}

return { ...gk, final_text: finalMessage };

const gk = $('Build Rejection Message').item.json;

return {
  status: gk.status,
  student_id: gk.student_id,
  full_name: gk.full_name,
  level_name: gk.level_name,
  candidates: gk.candidates,
  context: gk.context,
  retried_level: gk.retried_level
};

// Decides whether a zero-row "not_found" result is eligible for a single
// retry one level UP from what the parent stated.
//
// Why UP and not DOWN: the school's ERP promotes students to their next
// academic level in tb_student_registrations before the new academic session
// starts. During that window a parent naturally refers to the student's
// current-as-they-know-it (pre-promotion) class, but the DB already has the
// student in the next level up. So when the parent's stated level yields zero
// rows, the retry must search the level ABOVE it (JSS2 stated -> retry JSS3).
// This is the inverse of the "Step Down Level" pattern used elsewhere in the
// live workflow for report-fetching, where the caller already knows the
// current (post-promotion) level and steps DOWN to find historical records.
//
// Exactly one retry is attempted, never a cascade -- a parent being off by
// more than one promotion cycle is a different problem and should surface as
// not_found rather than silently searching the whole level list.
const LEVELS = [
    "junior secondary 1",
    "junior secondary 2",
    "junior secondary 3",
    "senior secondary 1",
    "senior secondary 2",
    "senior secondary 3"
];

const ALIASES = {
    "jss1": "junior secondary 1", "js1": "junior secondary 1",
    "jss2": "junior secondary 2", "js2": "junior secondary 2",
    "jss3": "junior secondary 3", "js3": "junior secondary 3",
    "sss1": "senior secondary 1", "ss1": "senior secondary 1",
    "sss2": "senior secondary 2", "ss2": "senior secondary 2",
    "sss3": "senior secondary 3", "ss3": "senior secondary 3"
};

function resolveLevel(raw) {
    const key = (raw || "").toLowerCase().trim();
    if (LEVELS.includes(key)) return key;
    if (ALIASES[key]) return ALIASES[key];
    return null;
}

const gk = $json; // Classify Match output: { status, student_id, full_name, level_name, candidates, context, retried_level }

if (gk.status !== "not_found") {
    // Only zero-row results are retry candidates; ambiguous/found are final as-is.
    return { ...gk, retry: false, retried_level: null, retry_level_query: null };
}

const statedLevel = $('Extract Student Info').item.json.level;
const resolved = resolveLevel(statedLevel);

if (!resolved) {
    // Unrecognized level -- flag and don't retry.
    return { ...gk, retry: false, retried_level: null, retry_level_query: null };
}

const idx = LEVELS.indexOf(resolved);
if (idx === LEVELS.length - 1) {
    // Already at the top level (senior secondary 3) -- nothing to step up to.
    return { ...gk, retry: false, retried_level: null, retry_level_query: null };
}

const steppedLevel = LEVELS[idx + 1];

return { ...gk, retry: true, retried_level: steppedLevel, retry_level_query: steppedLevel };

// Same classification logic as "Classify Match", run against the retry
// query's results (one level up from what the parent stated). Regardless of
// whether this retry itself finds a match, retried_level is stamped so
// downstream messaging can honestly say both the stated level and the
// stepped-up level were checked.
const rows = $input.all().map(item => item.json).filter(r => r && r.student_id);
const context = $('Extract Student Info').item.json.context;
const retriedLevel = $('Step Up Level').item.json.retried_level;

if (rows.length === 0) {
    return {
        status: "not_found",
        student_id: null,
        full_name: null,
        level_name: null,
        candidates: [],
        context,
        retried_level: retriedLevel
    };
}

if (rows.length === 1) {
    return {
        status: "found",
        student_id: rows[0].student_id,
        full_name: rows[0].full_name,
        level_name: rows[0].level_name,
        candidates: [],
        context,
        retried_level: retriedLevel
    };
}

return {
    status: "ambiguous",
    student_id: null,
    full_name: null,
    level_name: null,
    candidates: rows.map(r => ({
        student_id: r.student_id,
        full_name: r.full_name,
        level_name: r.level_name
    })),
    context,
    retried_level: retriedLevel
};
